import {bridgeSplitModifier,toneSplitModifier,prsSplitModifier} from '../electronics/switching/devices.mjs';
import {references,createReference,normaliseInstrument,instrumentSummary,instrumentCapabilities,instrumentFamilies,instrumentFamily,familyPickupLayouts,configureInstrumentDimensions,switchFamilies} from '../electronics/instrument/configuration.mjs';
import {componentPresets,pickupPresets} from '../electronics/response/assumptions.mjs';
import {allowed} from '../wiring-generator/model.mjs';
import {pickupLayoutArtwork} from '../wiring-generator/components.mjs';
const icons={guitar:'M3 7h18v10H3z M7 7v10m5-10v10m5-10v10',controls:'M12 3a9 9 0 1 0 0 18a9 9 0 1 0 0-18 M7 20v3m5-3v3m5-3v3',selector:'M3 5h18v14H3z M6 8v8m4-8v8m4-8v8m4-8v8',switching:'M6 4v16m12-16v16 M3 4h6m-6 8h6m-6 8h6m6-16h6m-6 8h6m-6 8h6',values:'M3 12h7m0-7v14m4-14v14m0-7h7',wiring:'M3 5h7v14h11 M7 5h6m4 14h6',advanced:'M3 6h18M3 12h18M3 18h18M8 3v6m8 0v6m-8 0v6'};
export function mountInstrumentPanel(root,{getInstrument,onChange,onReference,getKitAvailability}){
 const profiles=root.closest('form')?.querySelector('.forge-pickup-profiles');
 const doc=root.ownerDocument,e=(tag,text)=>{const n=doc.createElement(tag);if(text)n.textContent=text;return n;},groups=new Map();
 const identity=e('p');identity.id='forge-circuit-identity';identity.className='forge-circuit-identity';identity.setAttribute('aria-live','polite');const artwork=e('div');artwork.id='forge-pickup-layout-art';const description=e('dl');description.id='forge-instrument-summary';description.className='forge-configuration-summary';description.hidden=true;
 root.append(identity,artwork,description);root.classList.add('forge-control-console');
 for(const [id,title] of [['guitar','01 Guitar & Pickups'],['controls','02 Controls'],['selector','03 Selector'],['switching','04 Switching'],['values','05 Values'],['wiring','06 Wiring'],['advanced','07 Advanced']]){
  const details=e('details'),summary=e('summary'),caption=e('span',title),value=e('small'),body=e('div');details.className='forge-console-group';details.dataset.configureGroup=id;summary.id='configure-'+id;summary.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="${icons[id]}"/></svg>`;summary.append(caption,value);summary.setAttribute('aria-expanded','false');body.className='forge-console-body';details.append(summary,body);details.addEventListener('toggle',()=>{summary.setAttribute('aria-expanded',String(details.open));if(details.open)for(const g of groups.values())if(g.details!==details)g.details.open=false;});groups.set(id,{details,summary,value,body});root.append(details);
 }
 const limits=e('p');limits.id='forge-instrument-limit';limits.setAttribute('role','status');const availability=e('ul');availability.id='forge-capability-status';root.append(availability,limits);
 function edit(fn){const i=structuredClone(getInstrument());fn(i);onChange(normaliseInstrument(i));}
 function select(root,text,values,current,change,id){const label=e('label',text),s=e('select');s.id=id||'forge-setting-'+text.toLowerCase().replace(/[^a-z0-9]+/g,'-');for(const v of values){const o=e('option',typeof v==='object'?v.label:String(v));o.value=typeof v==='object'?v.value:String(v);s.append(o);}s.value=String(current);s.addEventListener('change',()=>change(s.value));label.append(s);root.append(label);return s;}
 function dimensions(changes){onChange(configureInstrumentDimensions(getInstrument(),changes));}
 let configurationKey='';
 function updateAvailability(cap){if(!availability.children.length)for(const label of ['Wiring','Response','Kit'])availability.append(e('li',label));for(const [index,[label,available]] of [['Wiring',cap.canGenerateWiring],['Response',cap.canAnalyseResponse],['Kit',getKitAvailability?getKitAvailability():cap.canBuildKit]].entries()){const item=availability.children[index];item.textContent=label+' '+(available?'available':'unavailable');item.dataset.available=String(available);}limits.textContent=cap.wiringReason||cap.reason;limits.hidden=!cap.reason;}
 function refresh(){const focused=doc.activeElement?.id,i=getInstrument(),cap=instrumentCapabilities(i),family=instrumentFamily(i),modifiers=i.switching||[],pots=i.controls.map(c=>c.pot),caps=i.controls.filter(c=>c.role==='tone').map(c=>c.capacitor);
  const nextKey=JSON.stringify({...i,selector:{...i.selector,selection:null},controls:i.controls.map(c=>({...c,position:null})),switching:modifiers.map(m=>({...m,position:null}))});if(nextKey===configurationKey){updateAvailability(cap);return;}configurationKey=nextKey;
  identity.textContent=i.layout+' · '+i.controlLayout+' · '+i.selector.family.replace('-way-','-WAY ').toUpperCase()+' · '+i.wiring.toUpperCase();artwork.innerHTML=pickupLayoutArtwork(i.pickups);artwork.setAttribute('aria-label',i.pickups.map(p=>p.position+' '+p.type).join(', '));
  const summaries={guitar:instrumentFamilies[family]+' · '+i.layout,controls:i.controls.filter(c=>c.role==='volume').length+' Volume · '+i.controls.filter(c=>c.role==='tone').length+' Tone'+(modifiers.length?' · '+modifiers.length+' Push/Pull':''),selector:i.selector.family.replaceAll('-',' '),switching:modifiers.length?modifiers.map(m=>m.pickup+' split').join(' · '):'Standard · no modifiers',values:[...new Set(pots)].join('/')+'k · '+[...new Set(caps)].join('/')+'µF',wiring:i.wiring==='modern'?'Modern':i.wiring.toUpperCase(),advanced:'Cable '+i.load.cableC+'pF · Input '+i.load.loadR+'MΩ'};
  for(const [id,g] of groups){g.value.textContent=summaries[id];g.body.replaceChildren();}
  const body=id=>groups.get(id).body;
  select(body('guitar'),'Starting reference',Object.entries(references).map(([value,r])=>({value,label:r.label})),i.reference||'',value=>onReference(createReference(value)),'forge-reference');
  select(body('guitar'),'Instrument',Object.entries(instrumentFamilies).map(([value,label])=>({value,label})),family,value=>dimensions({family:value}),'forge-family');select(body('guitar'),'Pickup layout',familyPickupLayouts[family],i.layout,value=>dimensions({layout:value}),'forge-pickup-layout');
  for(const p of i.pickups)select(body('guitar'),p.position+' pickup model',Object.entries(pickupPresets).filter(([id])=>p.type==='single'?id==='single':id!=='single').map(([value,a])=>({value,label:a.label})),p.assumption,value=>edit(next=>{next.pickups.find(x=>x.position===p.position).assumption=value;}));
  select(body('controls'),'Control layout',[...new Set(['1V1T','1V2T','2V2T',i.controlLayout])].map(value=>({value,label:value+(instrumentCapabilities(configureInstrumentDimensions(i,{controlLayout:value})).canGenerateWiring?'':' · description only')})),i.controlLayout,value=>dimensions({controlLayout:value}),'forge-control-layout');body('controls').append(e('p',i.controls.map(c=>c.id.replace(/([A-Z])/g,' $1')+' → '+c.assignments.join(' + ')).join('; ')));
  select(body('selector'),'Selector hardware',Object.keys(switchFamilies).map(value=>({value,label:value.replaceAll('-',' ')+(instrumentCapabilities(configureInstrumentDimensions(i,{selector:value})).canGenerateWiring?'':' · description only')})),i.selector.family,value=>dimensions({selector:value}),'forge-selector-family');body('selector').append(e('small','Change the current position in Circuit State.'));
  if(cap.canCoilSplit){const targets=(family==='prs'?['both']:i.layout==='HSS'?['bridge']:['neck','bridge']).filter(p=>{if(p==='both')return i.pickups.every(x=>x.coilAccess!=='two-conductor');const pickup=i.pickups.find(x=>x.position===p);return pickup?.coilAccess!=='two-conductor';});for(const pickup of targets)select(body('switching'),i.layout==='HSS'?'Bridge switching':pickup+' Tone hardware',[{value:'none',label:'Standard pot'},{value:'manual',label:'Push/Pull · Manual Coil Split'}],modifiers.some(m=>m.pickup===pickup)?'manual':'none',value=>edit(next=>{const list=(next.switching||[]).filter(m=>m.pickup!==pickup);if(value==='manual')list.push(family==='prs'?prsSplitModifier():i.layout==='HSS'?bridgeSplitModifier():toneSplitModifier(pickup));if(list.length)next.switching=list;else delete next.switching;}),'forge-'+pickup+'-switching');body('switching').append(e('small','Coil A retained. Host: '+(i.layout==='HSS'?'Master Volume':'matching Tone pot')+'. State is independent of the selector.'));}else body('switching').append(e('p','No validated manual switching for this arrangement.'));
  for(const c of i.controls){select(body('values'),c.id.replace(/([A-Z])/g,' $1')+' · kΩ',componentPresets[c.role+'Pot'],c.pot,value=>edit(next=>{next.controls.find(x=>x.id===c.id).pot=Number(value);}));if(c.role==='tone')select(body('values'),c.id.replace(/([A-Z])/g,' $1')+' capacitor · µF',allowed.neckCap,c.capacitor,value=>edit(next=>{for(const t of next.controls)if(t.capacitorGroup===c.capacitorGroup)t.capacitor=value;}));}
  select(body('wiring'),'Wiring style',i.layout==='HH'?allowed.wiring:[...new Set(['modern',i.wiring])],i.wiring,value=>edit(next=>{next.wiring=value;}));for(const c of i.controls.filter(c=>c.role==='volume'))select(body('wiring'),c.id.replace(/([A-Z])/g,' $1')+' treble bleed',allowed.bleed,c.bleed,value=>edit(next=>{next.controls.find(x=>x.id===c.id).bleed=value;}));select(body('wiring'),'Cavity shield',['yes','no'],i.shielding,value=>edit(next=>{next.shielding=value;}));
  for(const key of ['cableC','loadR'])select(body('advanced'),key==='cableC'?'Cable capacitance · pF':'Input resistance · MΩ',componentPresets[key],i.load[key],value=>edit(next=>{next.load[key]=Number(value);}));const nameLabel=e('label','My guitar · private local label'),name=e('input');name.id='forge-instrument-label';name.maxLength=80;name.value=i.label;name.addEventListener('change',()=>edit(next=>{next.label=name.value;}));nameLabel.append(name);body('advanced').append(nameLabel,e('small','Shared links omit private labels and notes.'));
  if(profiles){profiles.hidden=!['HH','HSS'].includes(i.layout);body('advanced').append(profiles);}
  description.replaceChildren();for(const [key,value] of [['Instrument',instrumentFamilies[family]],['Pickups',i.pickups.map(p=>p.position+' '+p.type).join('; ')],['Assignments',i.controls.map(c=>c.id.replace(/([A-Z])/g,' $1')+' → '+c.assignments.join(' + ')).join('; ')],['Controls',summaries.controls],['Switching',summaries.switching]]){const row=e('div');row.append(e('dt',key),e('dd',value));description.append(row);}description.setAttribute('aria-label',instrumentSummary(i));
  updateAvailability(cap);
  if(focused)doc.getElementById(focused)?.focus({preventScroll:true});
 }
 refresh();return {refresh};
}
